func (registry *entityRegistry) ByID(entityType data.EntityType, id data.EntityID) (data.Entity, bool) {
	value, ok := registry.byID[entityIDKey{entityType: entityType, id: id}]
	return value.Clone(), ok
}
func (registry *entityRegistry) ByName(name string) data.Entities {
	return registry.byName[name].Clone()
}
func (registry *entityRegistry) All() data.Entities { return registry.all.Clone() }
